// src/sales/objects/event_attendee.object.ts
import { expression } from "@objectstack/spec";
import { ObjectSchema as ObjectSchema7, Field as Field7 } from "@objectstack/spec/data";
var ATTENDEE_RESOLUTIONS = [
  { value: "contact", column: "crm_contact", label: "Contact", color: "#4169E1" },
  { value: "lead", column: "crm_lead", label: "Lead", color: "#FFA500" },
  { value: "user", column: "sys_user", label: "User", color: "#00AA00" },
  { value: "external", column: "external_name", label: "External", color: "#8A8A8A" }
];
var DEFAULT_ATTENDEE_TYPE = "contact";
var blank = (f) => `(!has(record.${f}) || isBlank(record.${f}))`;
var filled = (f) => `(has(record.${f}) && !isBlank(record.${f}))`;
var typeIs = (v) => `(has(record.attendee_type) && record.attendee_type == "${v}")`;
var typeIsNot = (v) => `(has(record.attendee_type) && record.attendee_type != "${v}")`;
