    response: Field7.select({
      group: "response",
      label: "Response",
      required: true,
      storage: { notNull: true },
      trackHistory: true,
      defaultValue: "no_response",
      options: [...ATTENDEE_RESPONSE_OPTIONS]
    }),
    is_organizer: Field7.boolean({
      group: "response",
      label: "Organizer",
      defaultValue: false
    }),
    // ⛔ NOT `readonly` — but the cross-reference this note used to carry is
    // retired, not merely reworded: `crm_campaign_member.added_date` was ruled
