// src/service/flows/case-actions.flow.ts
import { cel as cel2 } from "@objectstack/spec";

// src/service/objects/_case-assignment.ts
var CLAIMABLE_TARGET_STATUSES = [
  "in_progress",
  "waiting_customer",
  "waiting_support"
];
function createCaseRoundRobinAssign(hookName = "case_auto_assign") {
  return {
    name: hookName,
    object: "crm_case",
    events: ["beforeInsert"],
    priority: 250,
    description: "Assign ownerless new cases to the least-loaded service agent.",
    handler: async (ctx) => {
      const { input } = ctx;
      if (typeof input.owner_id === "string" && input.owner_id) return;
      const api = ctx.api;
      if (!api) return;
      try {
        const holders = await api.object("sys_user_position").find({
          where: { position: "service_agent" },
          fields: ["user_id"],
          top: 1e3
        });
        const agentIds = Array.from(
          new Set(
            (holders ?? []).map((r) => typeof r.user_id === "string" ? r.user_id : "").filter(Boolean)
          )
        );
        if (agentIds.length === 0) return;
        let best;
        let bestCount = Infinity;
        for (const agentId of agentIds) {
          const openCount = await api.object("crm_case").count({
            where: { owner_id: agentId, status: { $nin: ["resolved", "closed"] } }
          });
          if (openCount < bestCount) {
            bestCount = openCount;
            best = agentId;
          }
        }
        if (best) input.owner_id = best;
      } catch {
      }
    }
  };
}
function createCaseEscalationReassign(hookName = "case_escalation_reassign") {
  return {
    name: hookName,
    object: "crm_case",
    events: ["beforeUpdate"],
    priority: 250,
    runAs: "system",
    description: "Hand a case being escalated to the least-loaded service manager.",
    handler: async (ctx) => {
      if (ctx.dispatch?.mode === "per-row") return;
      const { input } = ctx;
      const previous = ctx.previous;
      if (!previous) return;
      if (input.status !== "escalated" || previous.status === "escalated") return;
      if (typeof input.owner_id === "string" && input.owner_id) return;
      const api = ctx.api;
      if (!api) return;
      const organizationId = typeof previous.organization_id === "string" && previous.organization_id !== "" ? previous.organization_id : void 0;
      const inOrganization = organizationId ? { organization_id: organizationId } : {};
      try {
        const holders = await api.object("sys_user_position").find({
          where: { position: "service_manager", ...inOrganization },
          fields: ["user_id"],
          top: 1e3
        });
        const managerIds = Array.from(
          new Set(
            (holders ?? []).map((r) => typeof r.user_id === "string" ? r.user_id : "").filter(Boolean)
          )
        );
        if (managerIds.length === 0) return;
        const currentOwner = typeof previous.owner_id === "string" && previous.owner_id || "";
        if (currentOwner && managerIds.indexOf(currentOwner) !== -1) return;
        let best;
        let bestCount = Infinity;
        for (const managerId of managerIds) {
          const openCount = await api.object("crm_case").count({
            where: { owner_id: managerId, status: { $nin: ["resolved", "closed"] }, ...inOrganization }
          });
          if (openCount < bestCount) {
            bestCount = openCount;
            best = managerId;
          }
        }
        if (best) input.owner_id = best;
      } catch {
      }
    }
  };
}
function createCaseSelfClaim(hookName = "case_self_claim") {
  return {
    name: hookName,
    object: "crm_case",
    events: ["beforeUpdate"],
    priority: 260,
    description: "Let a user claim an unowned open case by picking it up; the owner written is always the caller.",
    handler: async (ctx) => {
      if (ctx.dispatch?.mode === "per-row") return;
      const { input } = ctx;
      const previous = ctx.previous;
      if (!previous) return;
      const claimant = ctx.user?.id;
      if (typeof claimant !== "string" || !claimant) return;
      if (ctx.session?.isSystem) return;
      if ("owner_id" in input) return;
      if (typeof previous.owner_id === "string" && previous.owner_id) return;
      if (previous.status === "closed") return;
      if (previous.is_closed === true || previous.is_closed === 1) return;
      const next = input.status;
      if (typeof next !== "string" || next === previous.status) return;
      if (next !== "in_progress" && next !== "waiting_customer" && next !== "waiting_support") return;
      input.owner_id = claimant;
    }
  };
}

