        { label: "In Approval", value: "in_approval", color: "#FFA500" },
        { label: "Activated", value: "activated", color: "#00AA00" },
        { label: "Expired", value: "expired", color: "#FF0000" },
        { label: "Terminated", value: "terminated", color: "#666666" }
