    crm_opportunity: Field13.masterDetail("crm_opportunity", {
      label: "Opportunity",
      group: "basic",
      required: true,
      storage: { notNull: true },
      deleteBehavior: "cascade"
    }),
    // Deliberately left on the default, which the same escalation turns into
