      id: "win_rate_12m",
      title: "Win Rate (12M)",
      description: "Deals won as a share of all deals settled in the last 12 months",
      type: "metric",
      filter: { close_date: { $gte: "{12_months_ago}" } },
      filterBindings: { dateRange: false },
      colorVariant: "success",
      dataset: "opportunity_metrics",
