    // read-derived, so a rep's CSV carries their own book, not the org's.
    crm_lead: { allowCreate: true, allowRead: true, allowEdit: true, allowDelete: false, viewAllRecords: false, modifyAllRecords: false, readScope: "own", allowExport: true },
    crm_account: { allowCreate: true, allowRead: true, allowEdit: true, allowDelete: false, viewAllRecords: false, modifyAllRecords: false, readScope: "own", allowExport: true },
    // NO readScope: `crm_contact` is `controlled_by_parent` (master-detail to
