    crm_opportunity: { allowCreate: true, allowRead: true, allowEdit: true, allowDelete: false, viewAllRecords: false, modifyAllRecords: false, readScope: "own", allowExport: true },
    // NO readScope on quote/contract either: both are `controlled_by_parent`
