            leadStatus: { label: "\u52A0\u5165\u4EE5\u4E0B\u72B6\u6001\u7684\u7EBF\u7D22", options: { new: "\u65B0\u5EFA", contacted: "\u5DF2\u8054\u7CFB", qualified: "\u5DF2\u786E\u8BA4" } },
