// src/sales/pages/home.page.ts
var embeddedListView = (id, objectName, views, viewKey) => {
  const view = views.listViews?.[viewKey];
  if (!view) throw new Error(`home.page.ts: no saved view "${viewKey}" on ${objectName}`);
  return {
    type: "list-view",
    id,
    label: view.label,
    properties: {
      objectName,
      viewType: "grid",
      columns: view.columns,
      filter: view.filter,
      sort: view.sort
    }
  };
};
