var lineTotal = (l) => Math.round(l.quantity * l.unit_price * (1 - (l.discount ?? 0) / 100) * 100) / 100;
var linesTotal = (lines) => Math.round(lines.reduce((sum, l) => sum + lineTotal(l), 0) * 100) / 100;

