var COMPOSITION_ENV_VAR = "HOTCRM_COMPOSITION";
var HOTCRM_COMPOSITIONS = ["default", "saas"];
function resolveComposition(raw = process.env[COMPOSITION_ENV_VAR]) {
  const value = (raw ?? "").trim();
  if (value === "") return "default";
  if (HOTCRM_COMPOSITIONS.includes(value)) {
    return value;
  }
  throw new Error(
    `${COMPOSITION_ENV_VAR}="${value}" is not a HotCRM composition. Expected one of: ${HOTCRM_COMPOSITIONS.join(", ")} (or leave it unset for 'default').`
  );
}

